#[test]
fn proof_first_effective_label_countermodel() {
    let (path, source, _, _, mut runtime) = observer_runtime();
    prepare_observable_runtime(&mut runtime);
    let policy = observer_policy(observer_source_ref(&path, &source))
        .with_label(EvidenceSecurityLabel::new("public-base").with_class(M8SecurityClass::Public))
        .with_relation_label_override(RELATION_NAME,
            EvidenceSecurityLabel::new("private-effective").with_class(M8SecurityClass::Private))
        .with_relation_input_label(RELATION_NAME,
            EvidenceSecurityLabel::new("private-input").with_class(M8SecurityClass::Private));
    let view = runtime.export_observer_view(policy).expect("current M8 accepts override join");
    let row = view.rows().redacted_subject("relation-lineage")
        .expect("real relation occurrence emitted");
    assert_eq!(row.label().security_class(), M8SecurityClass::Public);
    println!("COUNTERMODEL: private relation join accepted, actual emitted relation label Public");
}

