#[test]
fn proof_first_private_arithmetic_has_secret_dependent_failure_outcome() {
    let source = r#"module ProofFirst.PrivateArithmetic
locus S
principal self
principal target
type Player
state player[id: Player] at S { hp: Int atk: Int }
Role[self] at S {
 when attack(target: Player) fails (StaleMembership, MissingCapability, MissingWitness, RouteUnavailable) {
  at S { player[self].atk = player[self].atk + 1 }
 }
}
"#;
    let checked = check_and_elaborate_surface_v0(FixtureSource::new("private-arithmetic.mir", source)).unwrap();
    assert!(checked.residual_obligations().entries().is_empty());
    for (secret, expected_failure) in [(0, false), (i64::MAX, true)] {
        let instance = M8Runtime::default().admit(checked.clone(), M8RuntimeAdmission::new(checked.program_identity().clone())).unwrap();
        let mut execution = instance.into_execution(M8ExecutionSeed::new()
            .with_int(hp_key(), 10).with_int(atk_key(), secret)
            .with_authority_state(owner_authority_state()));
        execution.try_enqueue(attack_request(valid_authority_use())).unwrap();
        let result = execution.serve_next_owner("S");
        assert_eq!(result.is_err(), expected_failure);
        assert_eq!(execution.snapshot().int(&hp_key()), Some(10));
        if expected_failure {
            let diagnostics = result.unwrap_err();
            assert_eq!(diagnostics.primary().kind(), M8ServeDiagnosticKind::DeclaredFailure(M8DeclaredFailure::RouteUnavailable));
            assert_eq!(execution.snapshot().int(&atk_key()), Some(i64::MAX));
        } else { assert_eq!(execution.snapshot().int(&atk_key()), Some(1)); }
        println!("private input {secret}: failure={expected_failure}; public hp unchanged");
    }
}
